class NodeCard extends ConsumerStatefulWidget {
  const NodeCard({
    super.key,
    required this.nodeId,
    required this.coin,
    required this.popBackToRoute,
  });

  final CryptoCurrency coin;
  final String nodeId;
  final String popBackToRoute;

  @override
  ConsumerState<NodeCard> createState() => _NodeCardState();
}

class _NodeCardState extends ConsumerState<NodeCard> {
  String _status = "Disconnected";
  late final String nodeId;
  bool _advancedIsExpanded = false;
  bool _connecting = false;

  Future<void> _notifyWalletsOfUpdatedNode(WidgetRef ref) async {
    final wallets = ref
        .read(pWallets)
        .wallets
        .where((e) => e.info.coin == widget.coin);
    final prefs = ref.read(prefsChangeNotifierProvider);

    switch (prefs.syncType) {
      case SyncingType.currentWalletOnly:
        for (final wallet in wallets) {
          if (ref.read(currentWalletIdProvider) == wallet.walletId) {
            unawaited(wallet.updateNode().then((value) => wallet.refresh()));
          } else {
            unawaited(wallet.updateNode());
          }
        }
        break;
      case SyncingType.selectedWalletsAtStartup:
        final List<String> walletIdsToSync = prefs.walletIdsSyncOnStartup;
        for (final wallet in wallets) {
          if (walletIdsToSync.contains(wallet.walletId)) {
            unawaited(wallet.updateNode().then((value) => wallet.refresh()));
          } else {
            unawaited(wallet.updateNode());
          }
        }
        break;
      case SyncingType.allWalletsOnStartup:
        for (final wallet in wallets) {
          unawaited(wallet.updateNode().then((value) => wallet.refresh()));
        }
        break;
    }
  }

  @override
  void initState() {
    nodeId = widget.nodeId;
    super.initState();
  }

  @override
  Widget build(BuildContext context) {
    final node = ref.watch(
      nodeServiceChangeNotifierProvider.select(
        (value) => value.getPrimaryNodeFor(currency: widget.coin),
      ),
    );
    final _node = ref.watch(
      nodeServiceChangeNotifierProvider.select(
        (value) => value.getNodeById(id: nodeId),
      ),
    )!;

    final testResult = ref.watch(
      pNodeTests.select((value) => value.resultFor(nodeId)),
    );

    if (node?.name == _node.name) {
      _status = "Connected";
    } else {
      _status = "Disconnected";
    }

    final isDesktop = Util.isDesktop;

    return RoundedWhiteContainer(
      padding: const EdgeInsets.all(0),
      borderColor: isDesktop
          ? Theme.of(context).extension<StackColors>()!.background
          : null,
      child: ConditionalParent(
        condition: !isDesktop,
        builder: (child) {
          return RawMaterialButton(
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(
                Constants.size.circularBorderRadius,
              ),
            ),
            onPressed: () async {
              // True: the user switched to this node.
              final connected = await showModalBottomSheet<bool>(
                backgroundColor: Colors.transparent,
                context: context,
                builder: (_) => NodeOptionsSheet(
                  nodeId: nodeId,
                  coin: widget.coin,
                  popBackToRoute: widget.popBackToRoute,
                ),
              );
              if (connected == true && context.mounted) {
                unawaited(
                  showFloatingFlushBar(
                    type: FlushBarType.success,
                    message: l10n.nodeConnectedTo(_node.name),
                    context: context,
                  ),
                );
              }
            },
            child: child,
          );
        },
        child: ConditionalParent(
          condition: isDesktop,
          builder: (child) {
            return Expandable(
              onExpandChanged: (state) {
                setState(() {
                  _advancedIsExpanded = state == ExpandableState.expanded;
                });
              },
              header: child,
              body: Padding(
                padding: const EdgeInsets.only(bottom: 24),
                child: Row(
                  children: [
                    const SizedBox(width: 66),
                    CustomTextButton(
                      text: _connecting
                          ? l10n.nodeConnecting
                          : l10n.commonConnect,
                      enabled: _status == "Disconnected" && !_connecting,
                      onTap: () async {
                        setState(() => _connecting = true);
                        try {
                          final result = await testNodeOf(
                            ref,
                            context,
                            _node,
                            widget.coin,
                          );
                          if (!result.passed) {
                            if (context.mounted) {
                              unawaited(
                                showFloatingFlushBar(
                                  type: FlushBarType.warning,
                                  iconAsset: Assets.svg.circleAlert,
                                  message: result.problem!,
                                  context: context,
                                ),
                              );
                            }
                            return;
                          }

                          // The user chose it: the app leaves it.
                          ref
                              .read(prefsChangeNotifierProvider)
                              .setNodeChosenByUser(
                                widget.coin.identifier,
                                true,
                              );
                          await ref
                              .read(nodeServiceChangeNotifierProvider)
                              .setPrimaryNodeFor(
                                coin: widget.coin,
                                node: _node,
                                shouldNotifyListeners: true,
                              );

                          await _notifyWalletsOfUpdatedNode(ref);
                          if (context.mounted) {
                            unawaited(
                              showFloatingFlushBar(
                                type: FlushBarType.success,
                                message: l10n.nodeConnectedTo(_node.name),
                                context: context,
                              ),
                            );
                          }
                        } finally {
                          if (mounted) setState(() => _connecting = false);
                        }
                      },
                    ),
                    const SizedBox(width: 48),
                    CustomTextButton(
                      text: l10n.commonDetails,
                      onTap: () {
                        Navigator.of(context).pushNamed(
                          NodeDetailsView.routeName,
                          arguments: Tuple3(
                            widget.coin,
                            widget.nodeId,
                            widget.popBackToRoute,
                          ),
                        );
                      },
                    ),
                  ],
                ),
              ),
            );
          },
          child: Padding(
            padding: EdgeInsets.all(isDesktop ? 16 : 12),
            child: Row(
              children: [
                Container(
                  width: isDesktop ? 40 : 24,
                  height: isDesktop ? 40 : 24,
                  decoration: BoxDecoration(
                    color: _node.id.startsWith(DefaultNodes.defaultNodeIdPrefix)
                        ? Theme.of(context)
                              .extension<StackColors>()!
                              .buttonBackSecondary
                        : Theme.of(context)
                              .extension<StackColors>()!
                              .infoItemIcons
                              .withOpacity(0.2),
                    borderRadius: BorderRadius.circular(100),
                  ),
                  child: Center(
                    child: SvgPicture.asset(
                      Assets.svg.node,
                      height: isDesktop ? 18 : 11,
                      width: isDesktop ? 20 : 14,
                      color:
                          _node.id.startsWith(DefaultNodes.defaultNodeIdPrefix)
                          ? Theme.of(context)
                                .extension<StackColors>()!
                                .accentColorDark
                          : Theme.of(context)
                                .extension<StackColors>()!
                                .infoItemIcons,
                    ),
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(_node.name, style: STextStyles.titleBold12(context)),
                      const SizedBox(height: 2),
                      Row(
                        children: [
                          Text(
                            _status == "Connected"
                                ? l10n.commonConnected
                                : l10n.commonDisconnected,
                            style: STextStyles.label(context),
                          ),
                          _NodeTestStatus(nodeId: nodeId),
                        ],
                      ),
                    ],
                  ),
                ),
                const SizedBox(width: 12),
                if (!isDesktop)
                  NodeSignalIcon(
                    nodeId: nodeId,
                    connected: _status == "Connected",
                  ),
                // On desktop only after a test, for how good it was.
                if (isDesktop && testResult != null) ...[
                  NodeSignalIcon(
                    nodeId: nodeId,
                    connected: _status == "Connected",
                  ),
                  const SizedBox(width: 16),
                ],
                if (isDesktop)
                  SvgPicture.asset(
                    _advancedIsExpanded
                        ? Assets.svg.chevronUp
                        : Assets.svg.chevronDown,
                    width: 12,
                    height: 6,
                    color: Theme.of(context)
                        .extension<StackColors>()!
                        .textSubtitle1,
                  ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

/// The node's test, after its connection state: a spinner while one runs,
/// then how fast it answered or what kept it from passing.
class _NodeTestStatus extends ConsumerWidget {
  const _NodeTestStatus({required this.nodeId});

  final String nodeId;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final testing = ref.watch(
      pNodeTests.select((value) => value.isTesting(nodeId)),
    );
    final result = ref.watch(
      pNodeTests.select((value) => value.resultFor(nodeId)),
    );
    if (!testing && result == null) return const SizedBox.shrink();

    final style = STextStyles.label(context);
    return Flexible(
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(" · ", style: style),
          if (testing)
            SizedBox(
              width: 10,
              height: 10,
              child: CircularProgressIndicator(
                strokeWidth: 1.5,
                color: style.color,
              ),
            )
          else
            Flexible(
              child: Text(
                result!.short,
                overflow: TextOverflow.ellipsis,
                style: result.passed
                    ? style
                    : style.copyWith(
                        color: Theme.of(context)
                            .extension<StackColors>()!
                            .accentColorRed,
                      ),
              ),
            ),
        ],
      ),
    );
  }
}
